# Regular content records get a separate, typed delete action. Singleton settings
# remain editable but cannot be deleted through the assistant.
for _kind in tuple(ACTION_FIELDS):
    if _kind.endswith("_update") and _kind not in {
        "theme_update", "announcement_update", "website_settings_update",
    }:
        ACTION_FIELDS[f"{_kind[:-7]}_delete"] = []

ACTION_KINDS = list(ACTION_FIELDS)

def _action_output_schema(kind):
    fields = ACTION_FIELDS[kind]
    return {
        "type": "object",
        "properties": {
            "kind": {"type": "string", "enum": [kind]},
            "record_id": {"type": ["integer", "null"]},
            "summary": {"type": "string"},
            "values": {
                "type": "object",
                "properties": {
                    name: {"anyOf": [VALUE_FIELDS[name]["schema"], {"type": "null"}]}
                    for name in fields
                },
                "required": fields,
                "additionalProperties": False,
            },
            "image_indices": {"type": "array", "items": {"type": "integer"}, "maxItems": 10},
            "replace_images": {"type": "boolean"},
        },
        "required": ["kind", "record_id", "summary", "values", "image_indices", "replace_images"],
        "additionalProperties": False,
    }


OUTPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "reply": {"type": "string"},
        "needs_clarification": {"type": "boolean"},
        "question": {"type": ["string", "null"]},
        "actions": {
            "type": "array",
            "maxItems": 10,
            "items": {"anyOf": [_action_output_schema(kind) for kind in ACTION_KINDS]},
        },
    },
    "required": ["reply", "needs_clarification", "question", "actions"],
    "additionalProperties": False,
}
